#!/usr/bin/env node
/**
 * gen-neomind-changelog.js
 *
 * 从 camthink-ai/NeoMind 仓库拉取 CHANGELOG.md,生成 wiki 的
 * 「NeoMind 版本发布说明」页面(zh + en),实现构建时自动同步,
 * 无需手工维护内容。
 *
 * - 生成物:docs/0-neomind/product-overview/5-release-notes.md
 *           i18n/en/.../0-neomind/product-overview/5-release-notes.md
 * - 策略:最新 1 个版本展开要点(小节标题 + 首条 bullet 摘要),
 *         其后 2 个版本列小节标题,更早版本生成速览表。
 * - 网络失败时回退使用仓库内已生成的基线文件(不阻断构建)。
 * - 文件头带 AUTO-GENERATED 标记:请勿手工编辑,改动会被覆盖。
 *
 * 用法:node scripts/gen-neomind-changelog.js
 */
const https = require('https');
const fs = require('fs');
const path = require('path');

const CHANGELOG_URL =
  'https://raw.githubusercontent.com/camthink-ai/NeoMind/main/CHANGELOG.md';
const CHANGELOG_PAGE =
  'https://github.com/camthink-ai/NeoMind/blob/main/CHANGELOG.md';

const ZH_OUT = path.join(
  __dirname, '..', 'docs', '0-neomind', 'product-overview', '5-release-notes.md');
const EN_OUT = path.join(
  __dirname, '..', 'i18n', 'en', 'docusaurus-plugin-content-docs', 'current',
  '0-neomind', 'product-overview', '5-release-notes.md');

function fetch(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { timeout: 15000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return fetch(res.headers.location).then(resolve, reject);
      }
      if (res.statusCode !== 200) {
        return reject(new Error('HTTP ' + res.statusCode + ' for ' + url));
      }
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

/** 解析 Keep-a-Changelog:版本块 → { ver, date, title, sections:[{h, first}] } */
function parseChangelog(md) {
  const versions = [];
  let cur = null;
  let curSection = null;
  for (const line of md.split('\n')) {
    const m = line.match(/^## \[(\d+\.\d+\.\d+)\] - (\d{4}-\d{2}-\d{2})(?:\s+—\s+(.*))?$/);
    if (m) {
      cur = { ver: m[1], date: m[2], title: (m[3] || '').replace(/</g, '＜').replace(/>/g, '＞').trim(), sections: [] };
      versions.push(cur);
      curSection = null;
      continue;
    }
    if (!cur) continue;
    const h = line.match(/^### (.+)$/);
    if (h) {
      curSection = { h: h[1].replace(/</g, '＜').replace(/>/g, '＞').trim(), first: '' };
      cur.sections.push(curSection);
      continue;
    }
    if (curSection && !curSection.first) {
      const bullet = line.match(/^\s*[-*] (.+)$/);
      if (bullet) {
        curSection.first = bullet[1]
          .replace(/\*\*/g, '')
          .replace(/`([^`]+)`/g, '$1')
          .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
          .replace(/</g, '＜')   /* MDX: 裸尖括号会被当 JSX 标签 */
          .replace(/>/g, '＞')
          .replace(/\s+/g, ' ')
          .trim();
      }
    }
  }
  return versions;
}

const clip = (s, n) => (s.length > n ? s.slice(0, n - 1).replace(/\s+\S*$/, '') + '…' : s);

function renderZh(v) {
  const latest = v[0];
  const mid = v.slice(1, 3);
  const old = v.slice(3);
  let out = `---
sidebar_label: "Release Notes"
sidebar_position: 5
description: "NeoMind 版本发布说明(自动同步自官方 CHANGELOG):最新版本要点、版本速览与完整变更链接。"
---

<!-- AUTO-GENERATED by scripts/gen-neomind-changelog.js — 请勿手工编辑,内容会被下次构建覆盖 -->

# 版本发布说明

本页由 [NeoMind 官方 CHANGELOG](${CHANGELOG_PAGE}) 自动生成并随 wiki 部署同步,摘要保留英文原文。升级步骤见 [安装与升级](../user-guide/install-setup)。

## 当前版本:NeoMind ${latest.ver}(${latest.date})

${latest.title ? `**${latest.title}**\n\n` : ''}${latest.sections.map((s) =>
    `- **${clip(s.h, 80)}**${s.first ? ' — ' + clip(s.first, 170) : ''}`
  ).join('\n')}

## 近期版本

${mid.map((x) => `### ${x.ver}(${x.date})${x.title ? '\n\n' + x.title : ''}\n\n${x.sections.map((s) => `- ${clip(s.h, 90)}`).join('\n')}`).join('\n\n')}

## 版本速览

| 版本 | 发布日期 | 主题 |
|------|----------|------|
${old.map((x) => `| [${x.ver}](${CHANGELOG_PAGE}) | ${x.date} | ${clip(x.title || '—', 60)} |`).join('\n')}

> 完整历史与细节见 [NeoMind CHANGELOG](${CHANGELOG_PAGE})。
`;
  return out;
}

function renderEn(v) {
  const latest = v[0];
  const mid = v.slice(1, 3);
  const old = v.slice(3);
  let out = `---
sidebar_label: "Release Notes"
sidebar_position: 5
description: "NeoMind release notes — auto-synced highlights from the official CHANGELOG, with a version index and full-history link."
---

<!-- AUTO-GENERATED by scripts/gen-neomind-changelog.js — do not edit by hand; regenerated on every deploy -->

# Release Notes

This page is generated from the [official NeoMind CHANGELOG](${CHANGELOG_PAGE}) and refreshed on every wiki deploy. For upgrade steps see [Install & Upgrade](../user-guide/install-setup).

## Current: NeoMind ${latest.ver} (${latest.date})

${latest.title ? `**${latest.title}**\n\n` : ''}${latest.sections.map((s) =>
    `- **${clip(s.h, 80)}**${s.first ? ' — ' + clip(s.first, 170) : ''}`
  ).join('\n')}

## Recent Versions

${mid.map((x) => `### ${x.ver} (${x.date})${x.title ? '\n\n' + x.title : ''}\n\n${x.sections.map((s) => `- ${clip(s.h, 90)}`).join('\n')}`).join('\n\n')}

## Version Index

| Version | Date | Theme |
|---------|------|-------|
${old.map((x) => `| [${x.ver}](${CHANGELOG_PAGE}) | ${x.date} | ${clip(x.title || '—', 60)} |`).join('\n')}

> Full history and details: [NeoMind CHANGELOG](${CHANGELOG_PAGE}).
`;
  return out;
}

(async () => {
  let md;
  try {
    md = await fetch(CHANGELOG_URL);
  } catch (e) {
    if (fs.existsSync(ZH_OUT)) {
      console.log('[changelog] fetch failed (' + e.message + '), keeping existing baseline files');
      return;
    }
    console.log('[changelog] fetch failed (' + e.message + ') and no baseline exists — skipping');
    return;
  }
  const versions = parseChangelog(md);
  if (!versions.length) {
    console.log('[changelog] parsed 0 versions — source format changed? skipping');
    return;
  }
  fs.mkdirSync(path.dirname(ZH_OUT), { recursive: true });
  fs.mkdirSync(path.dirname(EN_OUT), { recursive: true });
  // MDX 安全转义:正文里所有花括号/尖括号统一转成 HTML 实体(跳过 frontmatter)
  const mdxSafe = (md) => {
    const i = md.indexOf('---', 3) >= 0 ? md.indexOf('\n---', 3) + 5 : 0;
    return md.slice(0, i) + md.slice(i)
      .replace(/\{/g, '&#123;').replace(/\}/g, '&#125;')
      .replace(/</g, '&lt;').replace(/>/g, '&gt;');
  };
  fs.writeFileSync(ZH_OUT, mdxSafe(renderZh(versions)));
  fs.writeFileSync(EN_OUT, mdxSafe(renderEn(versions)));
  console.log('[changelog] generated release notes for ' + versions.length +
    ' versions (latest ' + versions[0].ver + ', ' + versions[0].date + ')');
})().catch((e) => {
  console.log('[changelog] unexpected error, skipping: ' + e.message);
  process.exit(0); // 生成失败不阻断构建
});
